namespace ghidra.app.plugin.core.datamgr.actions;

using docking;
using docking.action;
using docking.action;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util;
using ghidra.framework.main;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.program.model.dtarchive;
using ghidra.util;

/**
 * Action for opening file datatype archives.
 */
public class OpenProjectArchiveAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public OpenProjectArchiveAction(DataTypeManagerPlugin plugin) : base("Open Project Data Type Archive", plugin.getName())
    {
		this.plugin = plugin;

// ACTIONS - auto generated
		setMenuBarData(new MenuData(new string[] { "Open Project Archive..." }, null, "Archive"));

		setDescription("Opens a project data type archive in this data type manager.");
		setEnabled(true);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		PluginTool tool = plugin.getTool();
		ArchiveManager archiveManager = plugin.getArchiveManager();
		OpenVersionedFileDialog<ProjectDataTypeArchive> dialog = new(tool,
			"Open Project Data Type Archive", typeof(ProjectDataTypeArchive));
		dialog.setHelpLocation(new HelpLocation(HelpTopics.PROGRAM, "Open_File_Dialog"));
		dialog.addOkActionListener(ev => {
			DomainFile domainFile = dialog.getDomainFile();
			int version = dialog.getVersion();
			if (domainFile == null) {
				dialog.setStatusText("Please choose a Project Data Type Archive");
			}
			else {
				dialog.close();
				archiveManager.openProjectArchiveInTask(domainFile, version, Upgrade.ASK,
					Recover.ASK, true);
			}
		});

		tool.showDialog(dialog);
	}

}
